#[cfg(test)]
mod risk_result_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_risk_result_codec() {
        let mut original = RiskResult {
            req_id: 123456789,
            decision: 42,
            code: 1234,
            rule_id: 1234,
            ts_recv_ns: 123456789,
            ts_engine_ns: 123456789,
            text: "a".repeat(48),
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(RiskResultRef::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        RiskResult::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = RiskResult::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

